    's12_title' => '12. खाता स्थिति, निलंबन, और बंद करना।',
    's12_body' => 'हम अपने विवेक पर आपके खाते को फ्रीज, प्रतिबंधित, निलंबित, या बंद कर सकते हैं, या किसी विशिष्ट लेन-देन को अस्वीकार कर सकते हैं — जिसमें कानून का पालन करना, संदिग्ध धोखाधड़ी या दुरुपयोग की जांच करना, कानूनी या नियामक अनुरोध का जवाब देना, या जहां हम उचित रूप से मानते हैं कि ऐसा करना आपकी, किसी अन्य उपयोगकर्ता की, या Ledger की सुरक्षा के लिए आवश्यक है, शामिल है। जहां व्यावहारिक हो, हम आपको कारण बताएंगे और सहायता पेज के माध्यम से हम तक कैसे पहुंचें। आप किसी भी समय सहायता से संपर्क करके अपना खाता बंद कर सकते हैं, बशर्ते आपका शेष शून्य हो या निकाल लिया गया हो और कोई खुली जांच या लंबित लेन-देन न हो।',

    's13_title' => '13. सेवा उपलब्धता; अस्वीकरण।',
    's13_body' => 'हम सेवा को उपलब्ध और सटीक रखने के लिए काम करते हैं, लेकिन सेवा "जैसी है" प्रदान की जाती है और हम यह गारंटी नहीं देते कि यह निर्बाध, त्रुटि-मुक्त, या हर समय उपलब्ध होगी। हम अपने उचित नियंत्रण से बाहर की परिस्थितियों के कारण होने वाली देरी या विफलताओं के लिए उत्तरदायी नहीं हैं, जिसमें साझेदार बैंक, कार्ड नेटवर्क, या मध्यस्थ संस्था में आउटेज, या दैवीय आपदा की घटनाएं शामिल हैं। कानून द्वारा अनुमत पूरी सीमा तक, सेवा के आपके उपयोग से उत्पन्न किसी भी दावे के लिए Ledger की कुल देयता उस लेन-देन की राशि तक सीमित है जिसने दावे को जन्म दिया, सिवाय इसके कि जहां उपभोक्ता वित्तीय खातों की रक्षा करने वाला कानून व्यापक उपाय की आवश्यकता रखता है।',

    's14_title' => '14. विवाद समाधान।',
    's14_body' => 'यदि आपके और Ledger के बीच कोई असहमति उत्पन्न होती है, तो हम आपसे अनुरोध करते हैं कि आप पहले सहायता से संपर्क करें ताकि हम इसे सीधे हल करने का प्रयास कर सकें — अधिकांश मुद्दों को इस तरह से संभाला जा सकता है। यदि किसी विवाद को अनौपचारिक रूप से हल नहीं किया जा सकता है, तो कोई भी पक्ष लागू कानून के तहत उपलब्ध किसी भी उपाय को अपना सकता है। इन शर्तों में कुछ भी उपभोक्ता संरक्षण कानून के तहत आपके किसी भी अधिकार को सीमित नहीं करता है कि आप अपने राज्य या संघीय नियामक के साथ विवाद उठा सकें।',

    's15_title' => '15. गोपनीयता।',
    's15_body' => 'आपकी व्यक्तिगत और वित्तीय जानकारी के साथ हमारा व्यवहार — हम क्या एकत्र करते हैं, हम इसका उपयोग कैसे करते हैं, हम इसे किसके साथ साझा कर सकते हैं (जैसे साझेदार बैंक, पहचान-सत्यापन प्रदाता, और सेवा को संचालित करने के लिए आवश्यक कार्ड नेटवर्क), और आपके लिए उपलब्ध विकल्प — हमारे गोपनीयता प्रथाओं में वर्णित है। हम केवल सेवा पर लागू कानून का संचालन, सुरक्षा, और अनुपालन करने के लिए आपकी पहचान और खाता जानकारी का उपयोग करते हैं, और हम आपकी व्यक्तिगत जानकारी नहीं बेचते हैं।',

    's16_title' => '16. इन शर्तों में परिवर्तन।',
    's16_body' => 'हम सेवा, हमारे साझेदार बैंकों, या लागू कानून में परिवर्तनों को दर्शाने के लिए समय-समय पर इन शर्तों को अपडेट कर सकते हैं। जब हम कोई महत्वपूर्ण परिवर्तन करते हैं, तो हम ऊपर दी गई "अंतिम अपडेट" तारीख को अपडेट करेंगे और, जहां कानून द्वारा आवश्यक हो, अतिरिक्त सूचना प्रदान करेंगे। परिवर्तन प्रभावी होने के बाद सेवा का उपयोग जारी रखने का मतलब है कि आप अपडेट की गई शर्तों को स्वीकार करते हैं; यदि आप किसी परिवर्तन से सहमत नहीं हैं, तो आपको सेवा का उपयोग बंद कर देना चाहिए और अपना खाता बंद कर देना चाहिए।',

    's17_title' => '17. शासी कानून।',
    's17_body' => 'ये शर्तें संयुक्त राज्य अमेरिका के कानूनों और उस राज्य द्वारा शासित हैं जिसमें Ledger का संचालन मुख्यालय है, कानून के टकराव के सिद्धांतों की परवाह किए बिना, सिवाय इसके कि जहां आप निवास करते हैं उस क्षेत्राधिकार द्वारा एक अलग कानून लागू करना आवश्यक हो।',

    's18_title' => '18. हमसे संपर्क करें।',
    's18_body' => 'इन शर्तों, आपके खाते, या किसी विशिष्ट लेन-देन के बारे में प्रश्न किसी भी समय :support_link पेज के माध्यम से भेजे जा सकते हैं।',
    'support_link_text' => 'सहायता',
];
